//! ScreenGameplay controls, installed on the screen after its children exist.
use super::super::managers::screen::{Requests, capture};
use super::*;
use deadlib_lua::NativeStack;
use generated_players::dummy;
use sprites::set;

#[derive(Clone)]
struct Binding {
    store: Shared,
    requests: Arc<Mutex<Requests>>,
    enabled: [bool; crate::LUA_PLAYERS],
    method: &'static str,
}

impl Actors {
    // Screen allocation precedes generated player/theme adoption and controls.
    pub(in crate::rust_engine) fn top_screen_base(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
    ) -> Result<ActorScene, Error> {
        let function = vm.new_host_function_with_data(
            create_base,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            (self.store.clone(), context.clone()),
        )?;
        let Value::Number(id) = vm.call(function, &[])?[0] else {
            unreachable!()
        };
        Ok(ActorScene {
            owner: self.registry,
            id: id as u64,
        })
    }

    pub(in crate::rust_engine) fn bind_top_screen(
        &self,
        vm: &mut Vm,
        catalog: Value,
        screen_and_children: [Value; 5],
        enabled: [bool; crate::LUA_PLAYERS],
        requests: Arc<Mutex<Requests>>,
    ) -> Result<(), Error> {
        let mut captures = vec![
            Value::Table(self.registry),
            Value::Table(self.helpers),
            catalog,
        ];
        captures.extend(screen_and_children);
        let function = vm.new_host_function_with_data(
            install,
            &captures,
            Binding {
                store: self.store.clone(),
                requests,
                enabled,
                method: "",
            },
        )?;
        vm.call(function, &[]).map(|_| ())
    }
}

fn create_base(call: &mut HostCall<'_>) -> Result<(), Error> {
    let (store, context) = call
        .function_data::<(Shared, crate::SongLuaCompileContext)>()
        .unwrap()
        .clone();
    let scene = new_scene(call, &store)?;
    let previous = {
        let mut guard = store.lock().unwrap();
        let capture = !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed);
        std::mem::replace(&mut guard.constructing_capture, capture)
    };
    let result = (|| {
        let actor = dummy(call, &store, scene, "TopScreen", "ScreenGameplay", None)?;
        store.lock().unwrap().scenes.get_mut(&scene).unwrap().root = Some(actor);
        for (key, value) in [
            ("__songlua_player1_enabled", context.players[0].enabled),
            ("__songlua_player2_enabled", context.players[1].enabled),
        ] {
            set(call, actor, key, Value::Boolean(value))?;
        }
        let title = call.try_intern(context.main_title.as_bytes())?;
        set(call, actor, "__songlua_main_title", title)?;
        let bpm =
            crate::display_bpms_text(context.song_display_bpms, crate::song_music_rate(&context));
        let bpm = call.try_intern(bpm.as_bytes())?;
        set(call, actor, "__songlua_bpm_text", bpm)?;
        Ok(())
    })();
    store.lock().unwrap().constructing_capture = previous;
    if let Err(error) = result {
        release(call, &store, scene)?;
        return Err(error);
    }
    call.push(Value::Number(scene as f64))
}

// Bound methods retain the original screen, enabled players and backing slots.
// Replacing the published screen or GAMESTATE does not retarget saved methods.
fn install(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Binding>().unwrap().clone();
    let catalog = table(call, call.captures()[2])?;
    let slots = get(call, catalog, b"game_state_slots")?;
    let screen = table(call, call.captures()[3])?;
    let mut captures = call.captures().to_vec();
    captures[2] = slots;
    let wheel = call.try_new_table()?;
    call.with_roots(&[Value::Table(wheel)], |call| {
        captures.push(Value::Table(wheel));
        for method in [
            "IsLocked",
            "GetSelectedSection",
            "GetSelectedSong",
            "GetSelectedType",
            "GetSortOrder",
            "ChangeSort",
            "SetOpenSection",
            "Move",
        ] {
            let function = call.new_host_function_with_data(
                callback,
                &captures,
                Binding {
                    method,
                    ..data.clone()
                },
            )?;
            set(call, wheel, method, function)?;
        }
        for method in [
            "GetScreenType",
            "SetMinSecondsToMusic",
            "GetChild",
            "GetLifeMeter",
            "StartTransitioningScreen",
            "SetNextScreenName",
            "SetPrevScreenName",
            "GetNextScreenName",
            "GetPrevScreenName",
            "GetGoToOptions",
            "GetEditState",
            "GetCurrentRowIndex",
            "GetNumRows",
            "GetOptionRow",
            "SetOptionRowIndex",
            "RedrawOptions",
            "IsPaused",
            "PauseGame",
            "AllAreOnLastRow",
            "GetMusicWheel",
            "GetNextCourseSong",
            "PostScreenMessage",
            "SetProfileIndex",
            "Cancel",
            "Continue",
            "Finish",
            "Load",
            "begin_backing_out",
        ] {
            let function = call.new_host_function_with_data(
                callback,
                &captures,
                Binding {
                    method,
                    ..data.clone()
                },
            )?;
            set(call, screen, method, function)?;
        }
        Ok(())
    })
}

fn argument(call: &HostCall<'_>, index: usize) -> Value {
    let offset = usize::from(matches!(call.arguments().first(), Some(Value::Table(_))));
    arg(call, index + offset)
}
fn string(call: &HostCall<'_>, value: Value) -> Option<String> {
    let Value::String(id) = value else {
        return None;
    };
    std::str::from_utf8(call.string_bytes(id)?)
        .ok()
        .map(str::to_owned)
}
fn integer(call: &HostCall<'_>, value: Value) -> Option<i32> {
    match value {
        Value::Number(value) if value.is_finite() => {
            Some(value.round().clamp(i32::MIN as f64, i32::MAX as f64) as i32)
        }
        Value::String(_) => {
            let value = string(call, value)?;
            value
                .trim()
                .parse()
                .ok()
                .or_else(|| value.trim().parse::<f32>().ok().map(|n| n.round() as i32))
        }
        _ => None,
    }
}

fn callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Binding>().unwrap().clone();
    let screen_value = call.captures()[3];
    let screen = table(call, screen_value)?;
    let first = argument(call, 0);
    match data.method {
        "SetMinSecondsToMusic" => {
            let receiver = table(call, arg(call, 0))?;
            let seconds = call.number(1)? as f32;
            if !seconds.is_finite() || !(0.0..=60.0).contains(&seconds) {
                return Err(call.error(b"music lead-in must be between 0 and 60 seconds"));
            }
            let key = call.try_intern(b"__songlua_min_seconds_to_music")?;
            call.raw_table_set(receiver, key, Value::Number(seconds as f64))?;
            return call.push(Value::Table(receiver));
        }
        "GetOptionRow" => {
            let name = if matches!(first, Value::String(_)) {
                string(call, first).unwrap_or_default()
            } else {
                integer(call, first)
                    .and_then(crate::top_screen_option_row_name_at)
                    .unwrap_or(crate::SONG_LUA_TOP_SCREEN_OPTION_ROWS[0])
                    .to_owned()
            };
            let scene = data
                .store
                .lock()
                .unwrap()
                .actors
                .get(&screen)
                .map(|a| a.scene)
                .ok_or_else(|| call.error(b"screen has been released"))?;
            let row = option_row(call, &data.store, scene, &name)?;
            return call.push(Value::Table(row));
        }
        "GetChild" => {
            let Some(name) = string(call, first) else {
                return call.push(Value::Nil);
            };
            let player = crate::top_screen_player_index(&name)
                .map(|i| (i, 4 + i))
                .or_else(|| crate::top_screen_life_meter_index(&name).map(|i| (i, 6 + i)));
            if let Some((index, slot)) = player {
                return call.push(if data.enabled[index] {
                    call.captures()[slot]
                } else {
                    Value::Nil
                });
            }
            let named = native_children::named_children(call, screen)?;
            return call.with_roots(&[named], |call| {
                let key = call.try_intern(name.as_bytes())?;
                let value = call.table_get(named, key)?;
                if !matches!(value, Value::Nil | Value::Table(_)) {
                    return Err(call.error(b"screen child table expected"));
                }
                call.push(value)
            });
        }
        "GetLifeMeter" => {
            let index = match first {
                Value::Number(n) if n >= 0. && n < crate::LUA_PLAYERS as f64 && n.fract() == 0. => {
                    Some(n as usize)
                }
                Value::String(id) => call.string_bytes(id).and_then(|s| {
                    if s.eq_ignore_ascii_case(b"P1") || s.eq_ignore_ascii_case(b"PlayerNumber_P1") {
                        Some(0)
                    } else if s.eq_ignore_ascii_case(b"P2")
                        || s.eq_ignore_ascii_case(b"PlayerNumber_P2")
                    {
                        Some(1)
                    } else {
                        None
                    }
                }),
                _ => None,
            };
            return call.push(
                index
                    .filter(|&i| data.enabled[i])
                    .map_or(Value::Nil, |i| call.captures()[6 + i]),
            );
        }
        "StartTransitioningScreen" => {
            let globals = helper(call, 5)?;
            let live = data
                .store
                .lock()
                .unwrap()
                .clock
                .live
                .load(std::sync::atomic::Ordering::Relaxed);
            let message = string(call, first);
            {
                let mut stack = call.native_stack()?;
                stack.push(globals)?;
                let globals_index = stack.top();
                side_effect(&mut stack, globals_index)?;
                if live {
                    let message = message
                        .as_ref()
                        .ok_or_else(|| stack.error(b"expected a screen transition message"))?;
                    capture(
                        &mut stack,
                        &data.requests,
                        globals_index,
                        crate::SongLuaLiveRequest::Transition(message.clone()),
                    )?;
                }
            }
            if live {
                for child in children(call, &data.store, screen)? {
                    play(call, &data.store, child, b"Off", None, true)?;
                }
                let named = native_children::named_children(call, screen)?;
                let out =
                    call.with_roots(&[named], |call| get(call, table(call, named)?, b"Out"))?;
                if out != Value::Nil {
                    transitions::start(call, &data.store, table(call, out)?)?;
                }
                data.requests.lock().unwrap().transition = message;
            }
            return call.push(screen_value);
        }
        _ => (),
    }
    let second = argument(call, 1);
    let arg_count = call.arguments().len()
        - usize::from(matches!(call.arguments().first(), Some(Value::Table(_))));
    let first_text = string(call, first);
    let row = integer(call, if arg_count > 1 { second } else { first });
    let slots = call.captures()[2];
    let wheel = call.captures()[8];
    let globals = helper(call, 5)?;
    let mut stack = call.native_stack()?;
    stack.push(screen_value)?;
    let owner = stack.top();
    let mut result = screen_value;
    let mut effect = false;
    match data.method {
        "GetScreenType" => stack.push_bytes(b"ScreenType_Gameplay")?,
        "GetGoToOptions" | "AllAreOnLastRow" | "IsLocked" => stack.push(Value::Boolean(false))?,
        "GetEditState" => stack.push_bytes(b"EditState_Playing")?,
        "GetSelectedType" => stack.push_bytes(b"WheelItemDataType_Song")?,
        "GetSelectedSection" => stack.push_bytes(b"")?,
        "GetSelectedSong" => stack.push(Value::Nil)?,
        "GetMusicWheel" => stack.push(wheel)?,
        "GetNumRows" => stack.push(Value::Number(
            crate::SONG_LUA_TOP_SCREEN_OPTION_ROWS.len() as f64
        ))?,
        "GetNextScreenName" | "GetPrevScreenName" | "GetCurrentRowIndex" | "IsPaused" => {
            let key = match data.method {
                "GetNextScreenName" => b"__songlua_next_screen_name".as_slice(),
                "GetPrevScreenName" => b"__songlua_prev_screen_name",
                "GetCurrentRowIndex" => b"__songlua_current_row_index",
                _ => b"__songlua_paused",
            };
            stack.get_field(owner as isize, key)?;
            if data.method == "IsPaused" {
                stack.push(Value::Boolean(stack.to_boolean(-1)))?;
            } else if data.method == "GetCurrentRowIndex" {
                let n = if stack.value(-1) == Some(Value::Nil) {
                    0
                } else {
                    checked_i64(&stack, -1)?
                };
                stack.push(Value::Number(n as f64))?;
            } else if stack.value(-1) == Some(Value::Nil) {
                stack.push_bytes(b"")?;
            } else {
                let text = string_bytes(&mut stack, -1)?;
                stack.push_bytes(&text)?;
            }
        }
        "SetNextScreenName" | "SetPrevScreenName" | "PauseGame" | "SetOptionRowIndex" => {
            let key = match data.method {
                "SetNextScreenName" => b"__songlua_next_screen_name".as_slice(),
                "SetPrevScreenName" => b"__songlua_prev_screen_name",
                "PauseGame" => b"__songlua_paused",
                _ => b"__songlua_current_row_index",
            };
            if data.method != "SetOptionRowIndex" || row.is_some() {
                stack.push_bytes(key)?;
                match data.method {
                    "PauseGame" => stack.push(Value::Boolean(!matches!(
                        first,
                        Value::Nil | Value::Boolean(false)
                    )))?,
                    "SetOptionRowIndex" => stack.push(Value::Number(row.unwrap().max(0) as f64))?,
                    _ => stack.push_bytes(first_text.as_deref().unwrap_or_default().as_bytes())?,
                }
                stack.set_table(owner as isize, false)?;
            }
            effect = true;
        }
        "GetSortOrder" | "GetNextCourseSong" | "ChangeSort" => {
            stack.push(slots)?;
            stack.get_field(
                -1,
                if data.method == "GetNextCourseSong" {
                    b"song"
                } else {
                    b"sort"
                },
            )?;
            let slot = stack.top();
            if data.method == "ChangeSort" {
                if let Some(name) = first_text {
                    stack.push(Value::Number(1.))?;
                    stack.push_bytes(name.as_bytes())?;
                    stack.set_table(slot as isize, true)?;
                }
                effect = true;
                result = wheel;
            } else {
                stack.push(Value::Number(1.))?;
                stack.get_table(slot as isize, true)?;
                if data.method == "GetSortOrder" {
                    if stack.value(-1) == Some(Value::Nil) {
                        stack.push_bytes(b"SortOrder_Group")?;
                    } else {
                        let bytes = string_bytes(&mut stack, -1)?;
                        stack.push_bytes(&bytes)?;
                    }
                } else if !matches!(stack.value(-1), Some(Value::Nil | Value::Table(_))) {
                    return Err(stack.error(b"song table expected"));
                }
            }
        }
        "SetOpenSection" | "Move" => {
            effect = true;
            result = wheel;
        }
        "RedrawOptions" | "PostScreenMessage" | "SetProfileIndex" | "Cancel" | "Continue"
        | "Finish" | "Load" | "begin_backing_out" => effect = true,
        _ => unreachable!(),
    }
    if effect {
        stack.push(globals)?;
        let index = stack.top();
        side_effect(&mut stack, index)?;
        stack.push(result)?;
    }
    stack.finish(1)
}

fn string_bytes(stack: &mut NativeStack<'_, '_>, index: isize) -> Result<Vec<u8>, Error> {
    let value = match stack.to_bytes(index)? {
        Some(bytes) => bytes.to_vec(),
        None => return Err(stack.error(b"string expected")),
    };
    if std::str::from_utf8(&value).is_err() {
        return Err(stack.error(b"UTF-8 string expected"));
    }
    Ok(value)
}

fn checked_i64(stack: &NativeStack<'_, '_>, index: isize) -> Result<i64, Error> {
    let value = stack.number(index)?;
    if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&value) {
        return Err(stack.error(b"integer out of range"));
    }
    Ok(value as i64)
}
fn side_effect(stack: &mut NativeStack<'_, '_>, globals: usize) -> Result<(), Error> {
    stack.get_field(
        globals as isize,
        crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes(),
    )?;
    let count = if stack.value(-1) == Some(Value::Nil) {
        0
    } else {
        checked_i64(stack, -1)?
    };
    stack.push_bytes(crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes())?;
    stack.push(Value::Number(count.saturating_add(1) as f64))?;
    stack.set_table(globals as isize, false)
}

fn option_row(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    let row = dummy(call, store, scene, "OptionRow", name, None)?;
    let name_value = call.try_intern(name.as_bytes())?;
    let get_name = call.new_host_function(|call| call.push(call.captures()[0]), &[name_value])?;
    set(call, row, "GetName", get_name)?;
    let focus = call.new_host_function(|call| call.push(Value::Number(1.)), &[])?;
    set(call, row, "GetChoiceInRowWithFocus", focus)?;
    let frame = dummy(call, store, scene, "OptionRowFrame", "", Some(row))?;
    native_children::insert(call, row, "", Value::Table(frame))?;
    let title = screen_parts::text(call, store, scene, "Title", name)?;
    screen_parts::named(call, store, frame, "Title", title)?;
    let group = call.call(helper(call, 3)?, &[])?[0];
    call.with_roots(&[group], |call| {
        let text = crate::option_row_default_text(name);
        for index in 1..=crate::LUA_PLAYERS {
            let item = screen_parts::text(call, store, scene, "Item", &text)?;
            native_children::adopt(call, store, item, frame)?;
            call.raw_table_set(
                table(call, group)?,
                Value::Number(index as f64),
                Value::Table(item),
            )?;
        }
        native_children::insert(call, frame, "Item", group)
    })?;
    Ok(row)
}

//! Legacy lifecycle controls for differential integration tests.
//! Kept behind `test-support` so the tests exercise the actual compiled library
//! without copying its private live-mode or reset implementation.

pub use super::managers::screen::expose_publish as expose_screen_publication;
pub fn begin_legacy_screen_request_capture(lua: &mlua::Lua) {
    if lua.app_data_ref::<crate::live::SourceRequests>().is_none() {
        lua.set_app_data(crate::live::SourceRequests(Vec::new()));
    }
}
pub fn take_legacy_screen_requests(
    lua: &mlua::Lua,
) -> mlua::Result<(
    Option<crate::SongLuaLiveRequest>,
    Vec<crate::SongLuaLiveSourceRequest>,
)> {
    let output = crate::live::migration_take_output(lua)?;
    Ok((output.request, output.source_requests))
}
pub fn seed_legacy_transition(lua: &mlua::Lua, name: &str) {
    lua.set_app_data(crate::live::TransitionRequest(name.into()));
}
pub fn seed_rust_transition(runtime: &super::RustSongRuntime, name: &str) {
    runtime.screen.state.lock().unwrap().transition = Some(name.into());
}

pub fn install_legacy_input(lua: &mlua::Lua, screen: &mlua::Table) -> mlua::Result<()> {
    crate::input::install(lua, screen)
}
pub fn dispatch_legacy_input(
    lua: &mlua::Lua,
    event: &crate::SongLuaInputEvent<'_>,
) -> mlua::Result<(bool, Vec<String>)> {
    crate::input::dispatch(lua, event)
}
pub fn legacy_input_functions(lua: &mlua::Lua) -> Option<Vec<mlua::Function>> {
    crate::input::functions(lua)
}
pub fn legacy_input_event(
    lua: &mlua::Lua,
    event: &crate::SongLuaInputEvent<'_>,
) -> mlua::Result<mlua::Table> {
    crate::input::create_event(lua, event)
}
pub fn legacy_input_offline_compatible(lua: &mlua::Lua) -> Result<(), String> {
    crate::input::require_offline_compatible(lua)
}
pub use super::input::testing::{input_compiled_count, input_functions, install_input_controls};

pub fn reset_legacy_statistics(
    lua: &mlua::Lua,
    context: &crate::SongLuaCompileContext,
) -> mlua::Result<()> {
    crate::tables::reset_stage_stats(lua, context)
}
pub fn feed_legacy_statistics(
    stage: &mlua::Table,
    players: &[mlua::Table; crate::LUA_PLAYERS],
    frame: &crate::SongLuaLiveFrame,
) -> mlua::Result<()> {
    crate::live::migration_feed_statistics(stage, players, frame)
}
pub fn publish_legacy_live_players(
    lua: &mlua::Lua,
    players: [crate::SongLuaLivePlayer; crate::LUA_PLAYERS],
) {
    crate::live::migration_publish_live_players(lua, players)
}
pub fn take_legacy_player_writes(lua: &mlua::Lua) -> Vec<super::SongLuaLivePlayerWrite> {
    crate::live::migration_take_player_writes(lua)
}
pub fn legacy_live_players(
    lua: &mlua::Lua,
) -> Option<[crate::SongLuaLivePlayer; crate::LUA_PLAYERS]> {
    crate::live::migration_live_players(lua)
}
pub fn rust_live_players(
    runtime: &super::RustSongRuntime,
) -> Option<[crate::SongLuaLivePlayer; crate::LUA_PLAYERS]> {
    runtime.statistics.lock().unwrap().players
}
/// Retire statistics' additional public ownership before isolated catalog GC tests.
pub fn retire_statistics_globals(
    runtime: &mut super::RustSongRuntime,
) -> Result<(), deadlib_lua::Error> {
    runtime.vm.set_global(b"STATSMAN", deadlib_lua::Value::Nil)
}

/// Use the production noteskin manager and its actual actor factory as the oracle.
pub fn install_legacy_noteskin(
    lua: &mlua::Lua,
    context: &crate::SongLuaCompileContext,
    resolver: crate::SongLuaNoteskinResolver,
) -> mlua::Result<()> {
    crate::compile::migration_install_noteskin(lua, context, resolver)
}

/// Expose the retained song objects while GAMESTATE migration is in progress.
pub fn expose_catalog(runtime: &mut super::RustSongRuntime) -> Result<(), deadlib_lua::Error> {
    let value = runtime.vm.rooted(runtime.catalog)?;
    runtime.vm.set_global(b"catalog", value)
}

/// Release the staging catalog root for collection tests; call once, after exposing it.
pub fn release_catalog_root(
    runtime: &mut super::RustSongRuntime,
) -> Result<(), deadlib_lua::Error> {
    runtime.vm.unpin(runtime.catalog).map(|_| ())
}

/// Remove the newly installed public selection owners for isolated lifetime tests.
/// The caller separately releases the private catalog and its exposed test alias.
pub fn retire_game_state_globals(
    runtime: &mut super::RustSongRuntime,
) -> Result<(), deadlib_lua::Error> {
    for name in [
        "GAMESTATE",
        "GameState",
        "GetSongAndSteps",
        "GetPlayerOptionsString",
    ]
    .into_iter()
    .chain(crate::SONG_LUA_PLAYER_OPTIONS_KEYS)
    {
        runtime
            .vm
            .set_global(name.as_bytes(), deadlib_lua::Value::Nil)?;
    }
    Ok(())
}

pub fn expose_legacy_catalog(lua: &mlua::Lua) -> mlua::Result<()> {
    let state: mlua::Table = lua.globals().get("GAMESTATE")?;
    let result = lua.create_table()?;
    for (key, getter) in [("song", "GetCurrentSong"), ("course", "GetCurrentCourse")] {
        result.set(
            key,
            state
                .get::<mlua::Function>(getter)?
                .call::<mlua::Value>(state.clone())?,
        )?;
    }
    for (key, getter) in [
        ("steps", "GetCurrentSteps"),
        ("trails", "GetCurrentTrail"),
        ("player_states", "GetPlayerState"),
    ] {
        let values = lua.create_table()?;
        for index in 0..crate::LUA_PLAYERS {
            values.set(
                index + 1,
                state
                    .get::<mlua::Function>(getter)?
                    .call::<mlua::Value>((state.clone(), index))?,
            )?;
        }
        result.set(key, values)?;
    }
    let options = lua
        .app_data_ref::<crate::song_tables::SongLuaOptionLevels>()
        .expect("installed game state")
        .songs[3]
        .clone();
    result.set("current_song_options", options)?;
    let levels = lua
        .app_data_ref::<crate::song_tables::SongLuaOptionLevels>()
        .expect("installed game state")
        .songs
        .clone();
    result.set("song_options", lua.create_sequence_from(levels)?)?;
    let players = lua
        .app_data_ref::<crate::song_tables::SongLuaOptionLevels>()
        .expect("installed game state")
        .players
        .clone();
    let options = lua.create_table()?;
    for (index, levels) in players.into_iter().enumerate() {
        options.set(index + 1, lua.create_sequence_from(levels)?)?;
    }
    result.set("player_options", options)?;
    lua.globals().set("catalog", result)
}

/// Forward to the production group phases; the adapter owns their replacement.
pub fn expose_legacy_option_operations(lua: &mlua::Lua) -> mlua::Result<()> {
    use crate::lua_util::method_arg;
    let operations = lua.create_table()?;
    for name in [
        "Advance",
        "Restart",
        "ClearAttacks",
        "Apply",
        "RebuildAttacks",
    ] {
        operations.set(
            name,
            lua.create_function(move |lua, args: mlua::MultiValue| {
                let argument = |i| method_arg(&args, i).cloned().unwrap_or(mlua::Value::Nil);
                match name {
                    "Restart" => crate::song_tables::restart_stage_options(lua),
                    "ClearAttacks" => crate::song_tables::clear_active_attack_options(lua),
                    "Advance" => {
                        let seconds = lua.unpack::<f64>(argument(0))?;
                        if argument(1) == mlua::Value::Nil {
                            crate::song_tables::advance_option_levels(lua, seconds)
                        } else {
                            let table = lua.unpack::<mlua::Table>(argument(1))?;
                            let deltas = [table.raw_get(1)?, table.raw_get(2)?, table.raw_get(3)?];
                            crate::song_tables::advance_option_levels_with_clock_deltas(
                                lua, seconds, deltas,
                            )
                        }
                    }
                    _ => {
                        let player = lua.unpack::<usize>(argument(0))?;
                        if player >= crate::LUA_PLAYERS {
                            return Err(mlua::Error::runtime("Expected PlayerNumber"));
                        }
                        if name == "RebuildAttacks" {
                            let master = lua.unpack::<bool>(argument(1))?;
                            let table = lua.unpack::<mlua::Table>(argument(2))?;
                            let modifiers = table
                                .sequence_values::<String>()
                                .collect::<mlua::Result<Vec<_>>>()?;
                            crate::song_tables::rebuild_active_attack_options(
                                lua,
                                player,
                                master,
                                modifiers.iter().map(String::as_str),
                            )
                        } else {
                            let level = crate::song_tables::options_level(Some(&argument(1)))?;
                            let text = crate::read_string(argument(2))
                                .ok_or_else(|| mlua::Error::runtime("Expected modifiers string"))?;
                            let (players, songs) = {
                                let levels = lua
                                    .app_data_ref::<crate::song_tables::SongLuaOptionLevels>()
                                    .expect("installed option levels");
                                (levels.players[player].clone(), levels.songs.clone())
                            };
                            crate::song_tables::apply_modifiers_from_level(
                                lua, &players, &songs, &text, level,
                            )
                        }
                    }
                }
            })?,
        )?;
    }
    let catalog: mlua::Table = lua.globals().get("catalog")?;
    catalog.raw_set("option_operations", operations)
}

