            log(frame:GetChild('Title'):GetText(),items[1]:GetText(),items[2]:GetText(),type(row.SetUpdateFunction),type(frame.SetUpdateFunction))
        end
        for _,key in ipairs{'SpeedMod','speedmod','2',-1,1.5,false,string.char(255)} do
